#!/usr/bin/env node
// Writes copies of the demo's screenshot tests that register only the tests of
// some pages in one appearance, and prints the copies' names (relative to
// examples/demo) for `nsh test <file> --target web`. `nsh test` has no name
// filter, so the copy wraps `test` from "nsh/test": a test whose page or
// appearance is not asked for is never registered.
//
//   node .github/ci/subset-tests.mjs --scheme light --pages "gallery tabbar"
//
// A test's page is the first part of its name ("tabbar, light" →
// tabbar), or the page a file is about (`FILES`); its appearance is a part of
// its name equal to "light" or "dark".
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const demo = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "examples", "demo");

/** The test files the screenshot job runs, and the page a file is about (null: from the name). */
const FILES = [
  { file: "screenshots.test.tsx", page: null },
  { file: "separators.test.tsx", page: "lists" },
];

const args = process.argv.slice(2);
const arg = (name) => {
  const index = args.indexOf(`--${name}`);
  if (index < 0 || index + 1 >= args.length) throw new Error(`usage: subset-tests.mjs --scheme <light|dark> --pages "<page> ..."; --${name} is missing`);
  return args[index + 1];
};
const scheme = arg("scheme");
if (scheme !== "light" && scheme !== "dark") throw new Error(`--scheme must be light or dark, not "${scheme}"`);
const pages = arg("pages").split(/[\s,]+/).filter(Boolean);
if (!pages.length) throw new Error("--pages names no page");

const IMPORT = /^import\s*\{([^}]*)\}\s*from\s*"nsh\/test";\s*$/m;

for (const { file, page } of FILES) {
  if (page && !pages.includes(page)) continue;
  const source = readFileSync(join(demo, file), "utf8");
  const found = source.match(IMPORT);
  const names = found?.[1].split(",").map((name) => name.trim()).filter(Boolean) ?? [];
  if (!names.includes("test")) {
    throw new Error(`examples/demo/${file} does not import \`test\` in one \`import { ... } from "nsh/test";\` line: update .github/ci/subset-tests.mjs`);
  }
  const imports = names.map((name) => (name === "test" ? "test as nshTest" : name)).join(", ");
  const guard = [
    `import { ${imports} } from "nsh/test";`,
    `// Generated by .github/ci/subset-tests.mjs from ${file}: ${scheme}, ${pages.join(" ")}.`,
    `const SUBSET_PAGES: string[] = ${JSON.stringify(pages)};`,
    `const SUBSET_PAGE: string | null = ${JSON.stringify(page)};`,
    `const test = ((name: string, ...rest: unknown[]) => {`,
    `  const parts = name.split(",").map((part) => part.trim());`,
    `  if (!parts.includes(${JSON.stringify(scheme)})) return;`,
    `  if (!SUBSET_PAGES.includes(SUBSET_PAGE ?? parts[0])) return;`,
    `  (nshTest as unknown as (...args: unknown[]) => unknown)(name, ...rest);`,
    `}) as unknown as typeof nshTest;`,
  ].join("\n");
  const out = `ci-${scheme}-${file}`;
  writeFileSync(join(demo, out), source.replace(IMPORT, guard));
  console.log(out);
}
